<script setup lang="ts">
const {$platformApi}=useNuxtApp();const pending=ref(false);const error=ref('')
const form=reactive({name:'',slug:'',owner_email:'',plan:'starter',status:'trial'})
async function submit(){if(pending.value)return;pending.value=true;error.value='';try{const result=await $platformApi<{tenant:{id:string}}>('/admin/tenants',{method:'POST',body:form});await navigateTo(`/workspaces/${result.tenant.id}`)}catch{error.value='The workspace could not be created. Review the values and try again.'}finally{pending.value=false}}
</script>
<template><section><p class="eyebrow">New workspace</p><h1 class="title">Provision with intent.</h1><form class="panel form settings-form" @submit.prevent="submit"><label>Workspace name<input v-model="form.name" required maxlength="120"></label><label>Slug<input v-model="form.slug" required pattern="[a-z0-9-]{3,24}"></label><label>Initial owner email<input v-model="form.owner_email" required type="email"></label><label>Plan<select v-model="form.plan"><option>starter</option><option>growth</option><option>scale</option><option>enterprise</option></select></label><label>Status<select v-model="form.status"><option>trial</option><option>active</option></select></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="button" :disabled="pending">{{ pending?'Provisioning…':'Create workspace' }}</button></form></section></template>
